#include <list>
#include <stdexcept>

struct ThrowingType {
    ThrowingType() { 
        if (rand() % 10 == 0) throw std::runtime_error("Allocation fail"); 
    }
};

int main() {
    std::list<int> safe_list = {1, 2};
    // std::vector<int> unsafe_vector = {1, 2}; // Basic safety only

    // List insertion is strongly safe: if the node allocation fails,
    // the list state (size, iterators) is unchanged.
    try {
        safe_list.push_front(0); 
    } catch (...) {
        // safe_list is guaranteed to still contain {1, 2}
    }
}
